"""The dbt packages a project builds with: the bundled convention package and extensions."""

from __future__ import annotations

import importlib.metadata
import importlib.resources
from pathlib import Path

import yaml

from vecten_shared.config import VectenConfig
from vecten_shared.extensions import selected_entry_points
from vecten_shared.output import ExitCode, Failure
from vecten_shared.records import write_text_atomic
from vecten_shared.versions import VERSIONS

CONVENTION_PACKAGE = "vecten_convention"
ENTRY_POINT_GROUP = "vecten.dbt_packages"

_HEADER = (
    "# Generated by vecten before every dbt run; local paths are machine-specific, "
    "so this file is git-ignored.\n"
)


def convention_package_dir() -> Path:
    bundled = importlib.resources.files("vecten_platform") / "dbt_packages" / CONVENTION_PACKAGE
    return Path(str(bundled))


def convention_version() -> str:
    project = yaml.safe_load((convention_package_dir() / "dbt_project.yml").read_text())
    return str(project["version"])


def _entry_points():
    return importlib.metadata.entry_points(group=ENTRY_POINT_GROUP)


def extension_packages(config: VectenConfig) -> list[tuple[str, Path]]:
    found: list[tuple[str, Path]] = []
    for ep in selected_entry_points(config, ENTRY_POINT_GROUP, _entry_points()):
        path = Path(ep.load())
        if not path.is_dir():
            raise Failure(
                ExitCode.CONFIG,
                f"extension {ep.dist.name} declares dbt package {ep.name} at {path}, "
                "which is not a directory",
            )
        found.append((ep.name, path))
    return found


def write_packages_yml(dbt_dir: Path, config: VectenConfig) -> Path:
    bundled = convention_version()
    if bundled != VERSIONS.vecten_convention:
        raise Failure(
            ExitCode.CONFIG,
            f"the bundled {CONVENTION_PACKAGE} package is {bundled} but this vecten release "
            f"pins {VERSIONS.vecten_convention}; reinstall vecten",
        )
    locals_ = [convention_package_dir(), *(path for _, path in extension_packages(config))]
    body = yaml.safe_dump({"packages": [{"local": str(p)} for p in locals_]}, sort_keys=False)
    path = dbt_dir / "packages.yml"
    write_text_atomic(path, f"{_HEADER}# {CONVENTION_PACKAGE} {bundled}\n{body}")
    return path
